#include "MainWindow.hpp"
#include "ui_MainWindow.h" // Generated by the MOC

#include <memory>
#include <fmt/core.h>
#include "AddMaterialDialog.hpp"


MainWindow::MainWindow(QWidget* parent)
: QMainWindow(parent)
, ui(new Ui::MainWindow)
{
  ui->setupUi(this);


  connect(ui->actionAddMaterial, &QAction::triggered, this, &MainWindow::onAddMaterial);
  connect(ui->actionInterfParams, &QAction::triggered, this, &MainWindow::onInterfParams);
  connect(ui->actionOutputParams, &QAction::triggered, this, &MainWindow::onOutputParams);
  connect(ui->actionViewMaterials, &QAction::triggered, this, &MainWindow::onViewMaterials);

  connect(ui->addLayerButton, &QPushButton::clicked, this, &MainWindow::onAddLayer);
  connect(ui->removeLayerButton, &QPushButton::clicked, this, &MainWindow::onRemoveLayer);
  connect(ui->importStackButton, &QPushButton::clicked, this, &MainWindow::onImportStack);
  connect(ui->exportStackButton, &QPushButton::clicked, this, &MainWindow::onExportStack);
  connect(ui->computeStackButton, &QPushButton::clicked, this, &MainWindow::onComputeStack);

  
  m_materials["bulkSilica"] = Material("bulkSilica", 1e-9, 1e-6, 1e-6, 1, 1e6, 1.45, 73.2e9, 0.17, 1e-9);

  m_interferometer.beamWidth = 0.062;
  m_interferometer.wavelength = 1064e-9;
  m_interferometer.temperature = 290.0;
}


MainWindow::~MainWindow()
{
  delete ui;
}


void MainWindow::onAddMaterial()
{
  // TODO: Should the dialog be made once, reset and reused?
  //   Will need a reset function
  auto addMaterialDialog = std::make_shared<AddMaterialDialog>();

  if (addMaterialDialog->exec())
  {
    bool result = false;
    if (addMaterialDialog)
    {
      result = true;
    }
  }
}


